const originalLog = $('Build LLM Cache Key').first().json;
const cacheRow = $input.first().json;

let response;

try {
  response = JSON.parse(cacheRow.response_text);
} catch (e) {
  response = {
    cause_probable: cacheRow.response_text,
    actions_immediates: ['Vérifier le service concerné et consulter les logs récents.'],
    escalade_si: 'Si le problème persiste',
    severite_estimee: 'CRITICAL'
  };
}

return [{
  json: {
    ...originalLog,
    ...response,
    llm_source: cacheRow.llm_source || 'cache',
    llm_cache_hit: true
  }
}];

const log = $('Build LLM Prompt').first().json;

const staticFallbacks = {
  SECURITY:     'Vérifier les logs d\'accès, bloquer l\'IP source, notifier l\'équipe sécurité.',
  PERFORMANCE:  'Vérifier CPU/RAM/disque, identifier le processus fautif, redémarrer si nécessaire.',
  AVAILABILITY: 'Vérifier la connectivité réseau, l\'état du service et de ses dépendances.',
  DATA:         'Vérifier l\'intégrité des données, stopper les écritures, alerter l\'équipe DBA.',
  NETWORK:      'Vérifier la connectivité, les règles firewall, et les DNS.',
  SYSTEM:       'Vérifier les ressources système, les logs kernel, et l\'espace disque.'
};

function staticResponse(category) {
  return {
    cause_probable:     'LLM indisponible — réponse statique',
    actions_immediates: [staticFallbacks[category] || 'Analyser les logs et escalader.'],
    escalade_si:        'Si le problème persiste plus de 10 minutes',
    severite_estimee:   'CRITICAL',
    llm_source:         'static'
  };
}

// $json ici = réponse du HTTP Request node (ou objet erreur si "Continue on Fail")
const httpResult = $json;

// Si le nœud HTTP a échoué, $json contiendra un champ "error"
if (httpResult.error || !httpResult.choices) {
  return [{ json: { ...log, ...staticResponse(log.category) } }];
}

try {
  const rawText  = httpResult.choices[0].message.content.trim();
  const parsed   = JSON.parse(rawText);

  return [{
    json: {
      ...log,
      cause_probable:     parsed.cause_probable,
      actions_immediates: parsed.actions_immediates,
      escalade_si:        parsed.escalade_si,
      severite_estimee:   parsed.severite_estimee,
      llm_source:         'groq'
    }
  }];
} catch (e) {
  return [{ json: { ...log, ...staticResponse(log.category) } }];
}

function simpleHash(input) {
  let hash1 = 0x811c9dc5;
  let hash2 = 0x01000193;

  for (let i = 0; i < input.length; i++) {
    const char = input.charCodeAt(i);

    hash1 ^= char;
    hash1 = Math.imul(hash1, 16777619);

    hash2 ^= char;
    hash2 = Math.imul(hash2, 2166136261);
  }

  const part1 = (hash1 >>> 0).toString(16).padStart(8, '0');
  const part2 = (hash2 >>> 0).toString(16).padStart(8, '0');

  return (part1 + part2 + part1 + part2 + part1 + part2 + part1 + part2).substring(0, 64);
}

return items.map(item => {
  const log = item.json;

  const message = String(log.message ?? log.raw_log ?? '');

  const category = String(log.category ?? 'SYSTEM').toUpperCase();

  const afdState = String(log.afd_state ?? 'CRITICAL').toUpperCase();

  const normalizedMessage = message
    .toLowerCase()
    .replace(/\d{4}-\d{2}-\d{2}t?\s?\d{2}:\d{2}:\d{2}(\.\d+)?z?/gi, '<ts>')
    .replace(/\d{4}-\d{2}-\d{2}\s+\d{2}:\d{2}:\d{2}/g, '<ts>')
    .replace(/\b\d{1,3}(\.\d{1,3}){3}\b/g, '<ip>')
    .replace(/:\d{4,5}\b/g, ':<port>')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 256);

  const hashInput = `${normalizedMessage}|${category}|${afdState}`;
  const messageHash = simpleHash(hashInput);

  return {
    json: {
      ...log,
      category: category,
      afd_state: afdState,
      normalized_message: normalizedMessage,
      message_hash: messageHash,
      llm_cache_hit: false
    }
  };
});

const log = $('Build LLM Cache Key').first().json;

const userPrompt = `Tu es un ingénieur SRE expert en monitoring.
Un log CRITICAL a été détecté dans le service "${log.source_id}".
Log : ${log.message}
Catégorie : ${log.category || 'SYSTEM'}
Historique récent :
${JSON.stringify(log.recent_logs || [])}

Réponds UNIQUEMENT en JSON valide, sans texte avant ou après :
{
  "cause_probable": "...",
  "actions_immediates": ["action 1", "action 2", "action 3"],
  "escalade_si": "...",
  "severite_estimee": "HIGH"
}
Maximum 150 mots.`;

return [{
  json: {
    ...log,
    llm_payload: {
      model: $env.GROQ_MODEL ?? 'llama-3.1-8b-instant',
      messages: [{ role: 'user', content: userPrompt }],
      max_tokens: 300,
      temperature: 0.3,
      response_format: { type: "json_object" }
    }
  }
}];
